var people = new[]
{
    new { Name = "Alice", Age = 30 },
    new { Name = "Bob", Age = 25 },
    new { Name = "Alice", Age = 35 }
};
var distinct = people.DistinctBy(p => p.Name);
// [{ Name = "Alice", Age = 30 }, { Name = "Bob", Age = 25 }]

// MaxBy a property
var oldest = people.MaxBy(p => p.Age);
// { Name = "Alice", Age = 35 }

