using MoreLinq;

// De-duplicate by a key
var unique = orders.DistinctBy(o => o.CustomerId);

// The item with the largest value, not just the value
var biggest = orders.MaxBy(o => o.Total);

// Fixed-size batches
foreach (var batch in orders.Batch(100))
{
    await repo.SaveAllAsync(batch);
}

// Sliding windows
var averages = prices.Window(3).Select(w => w.Average());
